def most_common_char(s):
    if not s:
        raise ValueError('string must be non-empty')
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    max_count = max(counts.values())
    for ch in s:
        if counts[ch] == max_count:
            return ch
